"use client"

import animation from "react-useanimations/lib/notification4"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Notification V4" from https://useanimations.com (MIT): https://useanimations.com/icons/notification-v4
export function AnimatedNotificationV4(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="loop"
      {...props}
    />
  )
}
